import React, { useEffect, useState } from "react";
import styles from "./Browse.module.css";
import Navbar from "../component/Navbar/Navbar";
import Banner from "../component/Banner/Banner";
import MovieList from "../component/MovieList/MovieList";
import fetchMovie, { requests } from "../../fetchMovie";

function Browse() {
  const API_KEY = "13b2fccca48e8e9c5415b66d61ff1dd6";
  const BASE_URL = "https://api.themoviedb.org/3";
  const requests = {
    fetchTrending: `/trending/all/week?api_key=${API_KEY}&language=en-US`,
    fetchNetflixOriginals: `/discover/tv?api_key=${API_KEY}&with_network=123`,
    fetchTopRated: `/movie/top_rated?api_key=${API_KEY}&language=en-US`,
    fetchActionMovies: `/discover/movie?api_key=${API_KEY}&with_genres=28`,
    fetchComedyMovies: `/discover/movie?api_key=${API_KEY}&with_genres=35`,
    fetchHorrorMovies: `/discover/movie?api_key=${API_KEY}&with_genres=27`,
    fetchRomanceMovies: `/discover/movie?api_key=${API_KEY}&with_genres=10749`,
    fetchDocumentaries: `/discover/movie?api_key=${API_KEY}&with_genres=99`,
    fetchSearch: `/search/movie?api_key=${API_KEY}&language=en-US`,
  };

  const [movie, setMovie] = useState({ results: [] });
  const [banner, setBanner] = useState({});
  const IMAGE_BASE_URL = "https://image.tmdb.org/t/p/original";

  useEffect(() => {
    async function fetchMovie() {
      try {
        const urlsEndpoints = [
          requests.fetchTrending,
          requests.fetchNetflixOriginals,
          requests.fetchTopRated,
          requests.fetchActionMovies,
          requests.fetchComedyMovies,
          requests.fetchHorrorMovies,
          requests.fetchRomanceMovies,
          requests.fetchDocumentaries,
          requests.fetchSearch,
        ];
        const responses = await Promise.all(
          urlsEndpoints.map((url) => fetch(`${BASE_URL}${url}`))
        );
        responses.forEach((res) => {
          if (!res.ok) throw new Error("Failed to fetch");
        });

        const data = await Promise.all(responses.map((res) => res.json()));
        setMovie(data);
        console.log(data);
        const original = data[1];
        if (original.results.length > 0) {
          setBanner(
            original.results[Math.floor(Math.random() * movie.results.length)]
          );
          console.log(banner);
        }
      } catch (err) {
        console.error(err.message);
        return [];
      }
    }
    fetchMovie();
  }, []);

  // useEffect(() => {
  //   if (movie.results.length > 0) {
  //     setBanner(
  //       movie.results[Math.floor(Math.random() * movie.results.length)]
  //     );
  //     console.log(movie);
  //   }
  // }, [movie]);

  // console.log(banner);
  return (
    <div className={styles.browse}>
      <Navbar></Navbar>
      <Banner banner={banner} IMAGE_BASE_URL={IMAGE_BASE_URL}></Banner>
      <MovieList movie={movie}></MovieList>
    </div>
  );
}

export default Browse;
